CREATE TABLE IF NOT EXISTS staff_credentials (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,password_hash text NOT NULL,is_active boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE staff_credentials ADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS commission_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id uuid REFERENCES cities(id),merchant_category text,calculation_type text NOT NULL CHECK (calculation_type IN ('percentage','fixed')),value numeric(12,2) NOT NULL CHECK (value >= 0),minimum_amount numeric(12,2) NOT NULL DEFAULT 0,maximum_amount numeric(12,2),is_active boolean NOT NULL DEFAULT true,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS city_partner_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id uuid NOT NULL REFERENCES cities(id),requested_by uuid NOT NULL REFERENCES users(id),partner_type text NOT NULL CHECK (partner_type IN ('merchant','rider')),full_name text NOT NULL,phone varchar(20) NOT NULL,details jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS partner_requests_city_status_idx ON city_partner_requests(city_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS commission_rules_active_idx ON commission_rules(city_id,is_active);
